/**	psdirect.c**	This file contains the PostScript Direction package.** Change History** 1990/01/06 AGR V100	Completed file.* 1991/11/24 AGR V200	Upgraded to C++.AGR	V201	1994/11/26	Minimize includes.AGR	V202	1995/08/05	Port to Symantec C++.*/#include <math.h>				// V202 cos, sin#ifndef MAIN_ASSERT_H#include ":src:main:assert.h"	// assert#endif#ifndef PS_PSPROTO_H#include ":src:ps:psproto.h"		// PSDirection#endif#define DirectionLineWidth		pel(2.0)#define DirectionLineLength		mm(4.0)#define DirectionDotRadius		mm(0.5)void PSDirection(Point /* pos */,					Rect bounds, short which){	float xc,yc;		/* centre of sign */	float x, y;			/* centre of dot */	float xmin, xmax, ymin, ymax;	float a, b, dx, dy;	float theta;	float l = DirectionLineLength;	float r = DirectionDotRadius;		assert(which >= 1);	assert(which <= 8);		xc = (bounds.left + bounds.right) / 2.0;	yc = (bounds.top + bounds.bottom) / 2.0;		theta = deg((which - 7) * 45.0);		a = l * cos(theta);	b = l * sin(theta);		xmin = minf(-r, a);	ymin = minf(-r, b);		xmax = maxf(r, a);	ymax = maxf(r, b);		dx = -(xmin + xmax) / 2.0;	dy = -(ymin + ymax) / 2.0;		x = xc + dx;	y = yc + dy;		PSDot(x, y, r);		PS_moveto(x, y);	PS_rlineto(a, b);		PS_setlinewidth(DirectionLineWidth);	PS_stroke();}